function k({registerIndicator:x,sourceValues:g,nulls:v}){x({id:"oa-entropy",name:"Entropy (ENTROPY)",category:"Statistics",placement:"pane",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"length",type:"number",label:"Length",default:14,min:1,max:1e3,step:1}],plots:[{key:"entropy",type:"line",title:"Entropy",style:{color:"#ffeb3b",lineWidth:2}}],calc(h,y){const N=Math.max(1,Math.floor(Number(y.length)||14)),M=g(h,y.source??"close"),d=h.length,b=new Array(d).fill(NaN);let n=NaN,c=NaN,m=0,r=NaN;for(let i=0;i<d;i++){for(let o=0;o<N;o++){const t=i-o,e=t>=0?M[t]:NaN;Number.isFinite(e)&&(Number.isFinite(n)?(n=Math.min(n,e),c=Math.max(c,e)):(n=e,c=e),m+=1)}if(m<2)r=NaN;else{const o=c-n;if(o<=1e-10)r=0;else{const t=Math.min(Math.max(m,2),100),e=new Array(t).fill(0);let p=0;for(let a=0;a<N;a++){const s=i-a,l=s>=0?M[s]:NaN;if(!Number.isFinite(l))continue;const u=(l-n)/o,f=Math.floor(Math.min(Math.max(u,0),1-1e-10)*t),E=Math.max(0,Math.min(f,t-1));e[E]+=1,p+=1}if(p>0){let a=0;for(let l=0;l<t;l++){const u=e[l];if(u>0){const f=u/p;a+=-f*Math.log(f)}}const s=Math.log(t);r=s>1e-10?a/s:0}}}b[i]=r}return{entropy:v(b)}}})}export{k as default};
